// Normalise a Gumroad Ping (form-encoded) into the shared sales schema.
// Gumroad sends prices in cents. It does not send fees in the ping.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || {};
  const cents = Number(b.price || 0);
  const refunded = String(b.refunded) === 'true';
  out.push({ json: {
    order_id: 'gumroad-' + (b.sale_id || ''),
    platform: 'Gumroad',
    status: refunded ? 'refunded' : 'paid',
    sale_date: b.sale_timestamp ? new Date(b.sale_timestamp).toISOString() : new Date().toISOString(),
    product: b.product_name || '',
    quantity: Number(b.quantity || 1),
    currency: String(b.currency || 'usd').toUpperCase(),
    gross: (cents / 100).toFixed(2),
    fees: '',
    net: '',
    buyer_email: b.email || '',
    is_test: String(b.test) === 'true' ? 'yes' : 'no',
    logged_at: new Date().toISOString(),
  }});
}
return out;

// Normalise a Payhip webhook (JSON) into the shared sales schema.
// Payhip sends all amounts in cents and includes stripe_fee and payhip_fee.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || {};
  const gross = Number(b.price || 0);
  const fees = Number(b.stripe_fee || 0) + Number(b.payhip_fee || 0) + Number(b.paypal_fee || 0);
  const items = Array.isArray(b.items) ? b.items : [];
  const created = b.date || b.date_created;
  out.push({ json: {
    order_id: 'payhip-' + (b.id || ''),
    platform: 'Payhip',
    status: b.type === 'refunded'
      ? (Number(b.amount_refunded) >= gross ? 'refunded' : 'partially refunded')
      : 'paid',
    sale_date: created ? new Date(Number(created) * 1000).toISOString() : new Date().toISOString(),
    product: items.map(i => i.product_name).join(' + '),
    quantity: items.reduce((s, i) => s + Number(i.quantity || 1), 0) || 1,
    currency: String(b.currency || 'USD').toUpperCase(),
    gross: (gross / 100).toFixed(2),
    fees: (fees / 100).toFixed(2),
    net: ((gross - fees) / 100).toFixed(2),
    buyer_email: b.email || '',
    is_test: 'no',
    logged_at: new Date().toISOString(),
  }});
}
return out;
